def filter(
        self, iterable: Iterable[UnparsedVersionVar], prereleases: bool | None = None
    ) -> Iterator[UnparsedVersionVar]:

if prereleases is None:
    prereleases = self._prereleases
    if prereleases is None and any(s.prereleases for s in self._specs):
        prereleases = True

def selected():
    pending = []
    found_final = False
    for item in iterable:
        parsed = _coerce_version(item)
        if not all(s.contains(parsed, prereleases=True) for s in self._specs):
            continue
        if not parsed.is_prerelease or prereleases is True:
            found_final = True
            yield item
        elif prereleases is None:
            pending.append(item)
    if not found_final and prereleases is None:
        yield from pending

return selected()

def _site_data_dirs(self) -> list[str]:
        path = os.environ.get("XDG_DATA_DIRS", "")
        paths = [p for p in path.split(os.pathsep) if os.path.isabs(p)]
        if not paths:
            paths = (f"/usr/local/share{os.pathsep}/usr/share").split(os.pathsep)
        return [self._append_app_name_and_version(p) for p in paths]

def _site_config_dirs(self) -> list[str]:
        path = os.environ.get("XDG_CONFIG_DIRS", "")
        paths = [p for p in path.split(os.pathsep) if os.path.isabs(p)]
        if not paths:
            paths = ("/etc/xdg").split(os.pathsep)
        return [self._append_app_name_and_version(p) for p in paths]

def _append_app_name_and_version(self, *base: str) -> str:
        params = list(base[1:])
        if self.appname:
            params.append(self.appname)
            if self.version:
                params.append(self.version)
        path = os.path.join(base[0], *params)  # noqa: PTH118
        self._optionally_create_directory(path)
        return path
